package reality_test

// Precision claims of the beta quantile functions in prob: BetaQuantile,
// BetaQuantileComplement and BetaQuantileXY.
//
// The cases live in testdata/stress/precision_beta.json, generated by
// tools/stressgolden/beta.py from the 800-digit table
// testdata/stress/beta_quantile.json; each holds a function to the relative
// error its doc comment states for the case's region. The ratchet itself is
// TestPrecisionClaims in precision_test.go. The bounds that were fixed before
// the implementation existed are enforced separately, on the same table, by
// TestBetaQuantileOracle in prob.

import "github.com/davly/reality/prob"

func init() {
	registerPrecisionEvaluator("prob.BetaQuantile", func(c precisionCase) (float64, error) {
		return prob.BetaQuantile(argF(c, "a"), argF(c, "b"), argF(c, "p")), nil
	})
	registerPrecisionEvaluator("prob.BetaQuantileComplement", func(c precisionCase) (float64, error) {
		return prob.BetaQuantileComplement(argF(c, "a"), argF(c, "b"), argF(c, "p")), nil
	})
	registerPrecisionEvaluator("prob.BetaQuantileXY.y", func(c precisionCase) (float64, error) {
		_, y := prob.BetaQuantileXY(argF(c, "a"), argF(c, "b"), argF(c, "p"))
		return y, nil
	})
}
